import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>পুরো ফোল্ডারের ছবি এক ফরম্যাটে বদলাতে চান? এই ধাপে ধাপে গাইডে আপনি শিখবেন কীভাবে একসঙ্গে অনেক ছবি কনভার্ট করবেন।</p>\n<p>প্রক্রিয়াটি সহজ। ফোল্ডার গোছান, ব্যাচ আপলোড করুন, ফরম্যাট বেছে নিন, আর একটি ZIP ফাইলে সব ডাউনলোড করুন।</p>\n<p>শুরু থেকে শেষ পর্যন্ত প্রতিটি ধাপ এখানে দেওয়া হলো, সঙ্গে ভ্রমণের ছবি আর কাজের নথির জন্য আলাদা পরামর্শও আছে।</p>\n<h2 id=\"prepare-your-folder\">ফোল্ডার তৈরি করুন</h2>\n<p>যেসব ছবি কনভার্ট করতে চান, সেগুলো একটি ফোল্ডারে রাখুন। এতে আপলোডের সময় সব একসঙ্গে বেছে নেওয়া যায়।</p>\n<p>ফোল্ডারে অপ্রয়োজনীয় ফাইল থাকলে আগে সরিয়ে দিন। ভিডিও বা নথি ব্যাচে দেবেন না।</p>\n<p>ফোল্ডারের নাম পরিষ্কার রাখুন, যেমন trip-photos-jpg। এতে পরে খুঁজতে সুবিধা হয়।</p>\n<h2 id=\"upload-the-batch\">ব্যাচ আপলোড করুন</h2>\n<p>ব্রাউজারে <a href=\"/bn/bulk-image-convert-korun\">বাল্ক ইমেজ কনভার্টার</a> খুলুন। ফোল্ডারটি আপলোড এলাকায় ছেড়ে দিন বা ফাইলগুলো বেছে নিন।</p>\n<p>JPG, PNG, WebP, HEIC আর BMP একসঙ্গে দেওয়া যায়।</p>\n<p>ভুল ফাইল যোগ হলে সেটি তালিকা থেকে সরিয়ে দিন। বাকিগুলো যেমন আছে তেমনই থাকবে।</p>\n<h2 id=\"pick-the-target-format\">লক্ষ্য ফরম্যাট বেছে নিন</h2>\n<p>আউটপুট ফরম্যাট বেছে নিন। ছবির জন্য JPG, ওয়েবসাইটের জন্য WebP ভালো।</p>\n<p>লোগো বা লেখার জন্য PNG বেছে নিন। এতে প্রান্ত তীক্ষ্ণ থাকে।</p>\n<p>ফরম্যাট বেছে নেওয়ার আগে দেখুন ছবিগুলো কোথায় ব্যবহার হবে।</p>\n<h2 id=\"set-quality-once\">একবার কোয়ালিটি ঠিক করুন</h2>\n<p>ব্যাচে কোয়ালিটি একবার ঠিক করা হয়। সব ছবিতে একই কোয়ালিটি ব্যবহার হয়।</p>\n<p>সাধারণ কাজের জন্য 80 থেকে 90 ভালো। এতে ছবি পরিষ্কার থাকে।</p>\n<p>ব্যাচের আগে একটি ছবি পরীক্ষা করুন। কোয়ালিটি ঠিক থাকলে বাকিগুলোও ভালো হবে।</p>\n<p>কোয়ালিটি একবার সেট করার সময় ব্যাচের সবচেয়ে কঠিন ছবিটি দেখুন। লেখাযুক্ত ছবি সবচেয়ে বেশি কোয়ালিটি চায়। কঠিন ছবিতে ভালো ফল মানে সহজ ছবিতেও ভালো ফল।</p>\n<p>কোয়ালিটি ৮০ শতাংশে রাখলে বেশিরভাগ ছবি ভালো থাকে। ৯০ শতাংশে ফাইল বড় হয়, আর ৭০ শতাংশে লেখা ভেঙে যেতে পারে। ৮০ একটি নিরাপদ মাঝামাঝি।</p>\n<p>কোয়ালিটি সেট করার পর ব্যাচের একটি ছবি পরীক্ষা করুন। একটি ছবিতে ভালো ফল মানে পুরো ব্যাচে ভালো ফল। পরীক্ষা ছাড়া পুরো ব্যাচ চালাবেন না।</p>\n<p>WebP-তে একই কোয়ালিটিতে JPG-এর চেয়ে ছোট ফাইল হয়। WebP-তে ৮০ শতাংশ JPG-এর ৯০ শতাংশের সমান মান দেয়। তাই WebP-তে কোয়ালিটি একটু কম রাখা যায়।</p>\n<p>কোয়ালিটি সেট করার সময় ফাইলের আকার দেখুন। লক্ষ্য আকারের চেয়ে ফাইল বড় হলে কোয়ালিটি কমান। লক্ষ্য মিলে গেলে আর কমাবেন না।</p>\n<p>কোয়ালিটি একবার সেট করলে ব্যাচের সব ছবিতে একই সেটিং চলে। ভিন্ন ছবিতে ভিন্ন কোয়ালিটি দরকার হলে ছবিগুলো আলাদা ব্যাচে ভাগ করুন।</p>\n<p>কোয়ালিটি সেট করার সময় স্ক্রিনের উজ্জ্বলতা ঠিক রাখুন। অন্ধকার স্ক্রিনে ছবি ভালো লাগে, কিন্তু উজ্জ্বল স্ক্রিনে দাগ ধরা পড়ে। মাঝারি উজ্জ্বলতায় দেখুন।</p>\n<p>কোয়ালিটি সেটিং পরে বদলানো যায়। মূল ফাইল থাকলে আবার কনভার্ট করা যায়। তাই প্রথম চেষ্টায় নিখুঁত সেটিং না পেলেও সমস্যা নেই।</p>\n<p>কোয়ালিটি সেট করার সময় দলের মানদণ্ড মেনে চলুন। দলের সবাই একই কোয়ালিটি ব্যবহার করলে ছবির মান একই থাকে। মানদণ্ডটি লিখে রাখুন।</p>\n<h2 id=\"transparency-decisions\">স্বচ্ছতার সিদ্ধান্ত নিন</h2>\n<p>ব্যাচে স্বচ্ছ ছবি থাকলে সতর্ক থাকুন। JPG-তে স্বচ্ছতা থাকে না।</p>\n<p>স্বচ্ছ ছবি থাকলে PNG বা WebP আউটপুট বেছে নিন।</p>\n<p>স্বচ্ছ ছবি আলাদা ব্যাচে করুন। এতে ভুল হওয়ার আশঙ্কা কমে।</p>\n<h2 id=\"convert-and-watch\">কনভার্ট করে দেখুন</h2>\n<p>কনভার্ট বোতামে ট্যাপ করুন। টুলটি প্রতিটি ছবি একে একে কনভার্ট করে।</p>\n<p>অগ্রগতি বারে কতটি ছবি শেষ হলো তা দেখা যায়। বড় ব্যাচে কয়েক মিনিট লাগতে পারে।</p>\n<p>কাজ চলার সময় পাতাটি বন্ধ করবেন না। পাতা বন্ধ হলে ব্যাচ থেমে যাবে।</p>\n<h2 id=\"review-each-card\">প্রতিটি কার্ড দেখুন</h2>\n<p>ব্যাচ শেষ হলে প্রতিটি ছবির কার্ড দেখা যায়। মূল আর নতুন ফরম্যাট পাশাপাশি দেখা যায়।</p>\n<p>প্রতিটি ছবি একবার দেখুন। কোনো ছবি খারাপ লাগলে সেটি আলাদাভাবে আবার করুন।</p>\n<p>সব ছবি ঠিক লাগলে তবেই ডাউনলোড করুন।</p>\n<h2 id=\"download-as-zip\">ZIP হিসেবে ডাউনলোড করুন</h2>\n<p>ডাউনলোড বোতামে ট্যাপ করলে একটি ZIP ফাইল আসে। এতে সব কনভার্ট করা ছবি থাকে।</p>\n<p>ZIP ফাইল আনজিপ করে ছবিগুলো দেখুন। নাম আগের মতোই থাকে, শুধু ফরম্যাট বদলায়।</p>\n<p>আনজিপ করা ফোল্ডারটি আপনার কাজের ফোল্ডারে সরিয়ে নিন।</p>\n<ol>\n<li>ছবিগুলো একটি ফোল্ডারে গুছিয়ে রাখুন।</li>\n<li>ব্যাচ আপলোড করে লক্ষ্য ফরম্যাট বেছে নিন।</li>\n<li>কোয়ালিটি ঠিক করে কনভার্ট করুন।</li>\n<li>প্রতিটি কার্ড দেখে ZIP ডাউনলোড করুন।</li>\n</ol>\n<p>ZIP ফাইল ডাউনলোড করার আগে ভেতরে কতটি ছবি আছে তা দেখুন। ব্যাচে যতটি ছবি ছিল, ZIP-এ ততটি থাকা উচিত। কম থাকলে কোন ছবি বাদ পড়েছে তা দেখুন।</p>\n<p>ZIP ফাইলের নামে তারিখ আর ফরম্যাট লিখুন। নামে ফরম্যাট থাকলে পরে চিনতে সুবিধা হয়। webp-2026-11-22.zip-এর মতো নাম দিন।</p>\n<p>ZIP ফাইল ডাউনলোড করার পর তা খুলে একটি ছবি দেখুন। ছবি ঠিকমতো খুললে ZIP ঠিক আছে। ছবি নষ্ট হলে ব্যাচ আবার করুন।</p>\n<p>ZIP ফাইল বড় হলে ডাউনলোডে সময় লাগে। ধীর ইন্টারনেটে বড় ZIP ডাউনলোড করতে কয়েক মিনিট লাগতে পারে। ডাউনলোড শেষ না হওয়া পর্যন্ত অপেক্ষা করুন।</p>\n<p>ZIP থেকে ছবি বের করার সময় নতুন ফোল্ডার তৈরি করুন। নতুন ফোল্ডারে ছবি গোছানো থাকে। পুরোনো ফোল্ডারে বের করলে ফাইল মিশে যায়।</p>\n<p>ZIP ফাইলে ছবির নামের শেষাংশ নতুন ফরম্যাটে বদলে যায়। নামের মূল অংশ একই থাকে। নাম দেখে মূল ছবি চেনা যায়।</p>\n<p>ZIP ডাউনলোড ব্যর্থ হলে ব্রাউজারের সেটিং দেখুন। কিছু ব্রাউজার বড় ফাইল আটকে দেয়। অনুমতি দিয়ে আবার চেষ্টা করুন।</p>\n<p>ZIP ফাইল ফোনে খুলতে ফাইল ম্যানেজার ব্যবহার করুন। ফোনের ফাইল ম্যানেজার ZIP খুলতে পারে। না পারলে ফ্রি ZIP অ্যাপ ইনস্টল করুন।</p>\n<p>ZIP ফাইল শেয়ার করার আগে তার আকার দেখুন। বড় ZIP ইমেইলে যায় না। বড় ZIP ক্লাউড লিংক দিয়ে পাঠান।</p>\n<h2 id=\"fixing-failed-files\">ব্যর্থ ফাইল ঠিক করা</h2>\n<p>কোনো ছবি ব্যর্থ হলে সেটি আলাদাভাবে দেখুন। অনেক সময় ফরম্যাটের কারণে ব্যর্থ হয়।</p>\n<p>নষ্ট ফাইল থাকলে তা বাদ দিন। নতুন করে ছবি তুলুন বা স্ক্যান করুন।</p>\n<p>বারবার ব্যর্থ হলে ফাইলটি একক কনভার্টারে চেষ্টা করুন।</p>\n<h2 id=\"converting-again-to-another-format\">আবার অন্য ফরম্যাটে কনভার্ট করা</h2>\n<p>একই ছবি দুটি ফরম্যাটে দরকার হলে দুটি ব্যাচ চালান। প্রতিটি ব্যাচে আলাদা আউটপুট বেছে নিন।</p>\n<p>তবে কনভার্ট করা ফাইল থেকে আবার কনভার্ট করবেন না। সবসময় মূল ফাইল থেকে শুরু করুন।</p>\n<p>দুটি ব্যাচের ফাইল আলাদা ফোল্ডারে রাখুন। এতে গুলিয়ে যায় না।</p>\n<h2 id=\"mobile-batch-tips\">মোবাইলে ব্যাচ করার পরামর্শ</h2>\n<p>ফোনে ব্রাউজার খুলে ব্যাচ টুল চালান। গ্যালারি থেকে একাধিক ছবি বেছে নেওয়া যায়।</p>\n<p>ফোনে বড় ব্যাচ ধীর হতে পারে। বিশটির বেশি ছবি হলে ডেস্কটপে করা ভালো।</p>\n<p>ডাউনলোড করা ZIP ফাইল ফোনের ফাইল অ্যাপে পাবেন।</p>\n<h2 id=\"keeping-originals-safe\">মূল ফাইল নিরাপদে রাখা</h2>\n<p>মূল ছবি আলাদা ফোল্ডারে রাখুন। কনভার্ট করা ফাইল কাজের ফোল্ডারে রাখুন।</p>\n<p>ক্লাউডে ব্যাকআপ রাখলে নাম পরিষ্কার রাখুন। বছরখানেক পরেও যেন বোঝা যায় কোনটি মূল।</p>\n<p>ফোন বদলানোর সময় মূল ছবিগুলো আগে সরিয়ে নিন।</p>\n<p>মূল ছবি সংরক্ষণ করার জন্য আলাদা ফোল্ডার তৈরি করুন। মূল আর কনভার্ট করা ছবি এক ফোল্ডারে রাখবেন না। আলাদা ফোল্ডারে রাখলে ভুল কমে।</p>\n<p>মূল ছবি সংরক্ষণ করার সময় ফোল্ডারের নামে তারিখ লিখুন। নামে তারিখ থাকলে পরে খুঁজে পাওয়া সহজ হয়। originals-2026-11-22-এর মতো নাম দিন।</p>\n<p>মূল ছবি ক্লাউডে ব্যাকআপ রাখুন। কম্পিউটার নষ্ট হলে ক্লাউড থেকে ফাইল ফেরানো যায়। গুগল ড্রাইভ বা ড্রপবক্সে ব্যাকআপ রাখুন।</p>\n<p>মূল ছবি সংরক্ষণ করার সময় ফাইলের নাম বদলাবেন না। আসল নাম থাকলে পরে চেনা যায়। নাম বদলালে মূল আর কনভার্ট করা ফাইল মেলানো কঠিন হয়।</p>\n<p>মূল ছবি সংরক্ষণ করার পর কনভার্ট করা ছবি আলাদা ফোল্ডারে রাখুন। দুটি ফোল্ডারের নামে পার্থক্য রাখুন। নামে original আর converted লিখুন।</p>\n<p>মূল ছবি মুছে ফেলার আগে দুবার ভাবুন। মূল মুছে ফেললে আর ফেরানো যায় না। স্টোরেজ কম হলে মূল ক্লাউডে রেখে কম্পিউটার থেকে মুছুন।</p>\n<p>মূল ছবি সংরক্ষণ করার সময় মেটাডেটা রাখুন। তারিখ আর অবস্থানের তথ্য পরে কাজে লাগতে পারে। মেটাডেটা মুছে ফেলবেন না।</p>\n<p>মূল ছবি দলের সঙ্গে শেয়ার করার সময় শেয়ার করা ফোল্ডারে রাখুন। সবাই মূল দেখতে পেলে ভুল কমে। ব্যক্তিগত ফোল্ডারে রাখলে অন্যরা পায় না।</p>\n<p>মূল ছবি সংরক্ষণ করা একটি অভ্যাস। প্রতিবার কনভার্ট করার আগে মূল সংরক্ষণ করুন। অভ্যাসটি একদিন অনেক ক্ষতি থেকে বাঁচাবে।</p>\n<h2 id=\"sorting-before-upload\">আপলোডের আগে সাজানো</h2>\n<p>আপলোডের আগে ছবিগুলো ধরন অনুযায়ী সাজান। প্রতিকৃতি, পণ্য আর স্ক্রিনশট আলাদা করুন।</p>\n<p>ভিন্ন ধরনের ছবি আলাদা ব্যাচে করুন। এতে প্রতিটি ব্যাচের সেটিং ঠিক থাকে।</p>\n<p>কনভার্টের আগে ছবি ধরন অনুযায়ী সাজিয়ে ব্যাচে দিন। সাজানো ছবিতে ফল ভালো হয় আর সময় বাঁচে।</p>\n<h2 id=\"converting-trip-photos\">ভ্রমণের ছবি কনভার্ট করা</h2>\n<p>ভ্রমণের ছবি অ্যালবাম অনুযায়ী ব্যাচ করুন। প্রতিটি অ্যালবামের ছবি আলাদা ফোল্ডারে রাখুন।</p>\n<p>ভ্রমণের ছবি শেয়ার করার জন্য JPG-তে কনভার্ট করুন। ফাইল ছোট হয়।</p>\n<p>মূল ছবিগুলো ক্লাউডে ব্যাকআপ রাখুন। কমপ্রেস করা ছবি শুধু শেয়ার করার জন্য ব্যবহার করুন।</p>\n<p>ভ্রমণের ছবি কনভার্ট করার সময় ছবিগুলো তারিখ অনুযায়ী সাজান। তারিখের ক্রমে ছবি সাজালে গল্প বোঝা যায়। এলোমেলো ছবিতে গল্প হারিয়ে যায়।</p>\n<p>ভ্রমণের ছবি কনভার্ট করার সময় সেরা ছবিগুলো বেছে নিন। একশোটি ছবির মধ্যে বিশটি সেরা ছবি রাখুন। সব ছবি কনভার্ট করলে সময় নষ্ট হয়।</p>\n<p>ভ্রমণের ছবি কনভার্ট করার সময় WebP ব্যবহার করুন। WebP ফাইল ছোট হয়। ভ্রমণের অ্যালবাম শেয়ার করতে সুবিধা হয়।</p>\n<p>ভ্রমণের ছবি কনভার্ট করার পর তা অ্যালবামে সাজান। অ্যালবামে ছবির নিচে জায়গার নাম লিখুন। নাম থাকলে পরে মনে থাকে।</p>\n<p>ভ্রমণের ছবি কনভার্ট করার সময় মূল ছবি সংরক্ষণ করুন। মূল থেকে আবার কনভার্ট করা যায়। ভ্রমণের স্মৃতি হারানো উচিত নয়।</p>\n<p>ভ্রমণের ছবি কনভার্ট করার পর তা পরিবারের সঙ্গে শেয়ার করুন। শেয়ার করার আগে ফাইলের আকার দেখুন। বড় ফাইল শেয়ার করতে সময় লাগে।</p>\n<p>ভ্রমণের ছবি কনভার্ট করার সময় ছবির মান পরিষ্কার রাখুন। ভ্রমণের ছবিতে স্মৃতি থাকে। ঝাপসা ছবিতে স্মৃতি ফিকে হয়।</p>\n<p>ভ্রমণের ছবি কনভার্ট করার সময় ছবির অবস্থানের তথ্য রাখুন। অবস্থানের তথ্য থাকলে পরে জায়গা মনে থাকে।</p>\n<p>ভ্রমণের ছবি কনভার্ট করার পর তা ক্লাউডে ব্যাকআপ রাখুন। ফোন হারিয়ে গেলে ক্লাউড থেকে ছবি ফেরানো যায়।</p>\n<h2 id=\"converting-work-documents\">কাজের নথি কনভার্ট করা</h2>\n<p>কাজের নথির ছবি PDF বা JPG-তে কনভার্ট করুন। নথির ধরন অনুযায়ী ফরম্যাট বেছে নিন।</p>\n<p>লেখা থাকা নথিতে PNG ব্যবহার করুন। লেখা পরিষ্কার থাকে।</p>\n<p>নথির নামে তারিখ লিখুন। এতে পরে খুঁজতে সুবিধা হয়।</p>\n<h2 id=\"reusing-settings\">সেটিং আবার ব্যবহার করা</h2>\n<p>একই সেটিং বারবার ব্যবহার হলে তা লিখে রাখুন। যেমন ফরম্যাট আর কোয়ালিটি।</p>\n<p>কনভার্টের সেটিংগুলো একটা নোটে লিখে রাখুন। পরের ব্যাচে একই সেটিং ব্যবহার করা যায়, আর প্রতিবার নতুন করে ভাবতে হয় না।</p>\n<p>সেটিং বদলালে নোট আপডেট করুন। পুরনো সেটিং ব্যবহার করলে ভুল ফরম্যাটে ফাইল তৈরি হতে পারে।</p>\n<h2 id=\"converting-for-client-handover\">ক্লায়েন্টের কাছে দেওয়ার জন্য কনভার্ট করা</h2>\n<p>ক্লায়েন্টকে ছবি দেওয়ার আগে প্রতিটি ছবি দেখুন। ভুল ছবি গেলে খারাপ ছাপ পড়ে।</p>\n<p>ZIP ফাইলের নামে ক্লায়েন্টের নাম আর তারিখ লিখুন।</p>\n<p>ক্লায়েন্টকে মূল ফাইলও দিতে চাইলে আলাদাভাবে পাঠান।</p>\n<p>কাজের ধারা জানতে পড়ুন <a href=\"/bn/blog/batch-image-conversion-workflow\">ব্যাচ কনভার্টের কাজের ধারা</a> আর পূর্ণ গাইডের জন্য <a href=\"/bn/blog/bulk-image-converter-guide\">বাল্ক ইমেজ কনভার্টার গাইড</a>। কনভার্ট করতে <a href=\"/bn/image-convert-korun\">ইমেজ কনভার্টার</a> আর HEIC ছবির জন্য <a href=\"/bn/heic-to-jpg\">HEIC থেকে JPG টুল</a> ব্যবহার করুন।</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"একসঙ্গে কতটি ছবি কনভার্ট করা যায়?","answer":"বেশিরভাগ ব্যাচে দশ থেকে একশো ছবি করা যায়। খুব বড় ব্যাচ হলে পঞ্চাশটি করে ভাগ করে করুন। ফোনে বড় ব্যাচ ধীর হতে পারে, তাই বিশটির বেশি হলে ডেস্কটপে করা ভালো।"},{"question":"ব্যাচে কি মিশ্র ফরম্যাটের ছবি দেওয়া যায়?","answer":"হ্যাঁ। JPG, PNG, WebP, HEIC আর BMP একসঙ্গে দেওয়া যায়। টুলটি প্রতিটি ফাইল পড়ে একই আউটপুট ফরম্যাটে লিখে দেয়। তবে SVG ফাইল আলাদাভাবে করুন।"},{"question":"কনভার্ট শেষে সব ছবি কোথায় পাব?","answer":"ব্যাচ শেষ হলে একটি ZIP ফাইল ডাউনলোড হয়। এতে সব কনভার্ট করা ছবি থাকে। আনজিপ করে ছবিগুলো আপনার কাজের ফোল্ডারে সরিয়ে নিন।"},{"question":"একটি ছবি ব্যর্থ হলে কী করব?","answer":"সেই ছবিটি আলাদাভাবে আবার চেষ্টা করুন। ফরম্যাট দেখুন। বারবার ব্যর্থ হলে ফাইলটি নষ্ট কি না দেখুন, বা একক কনভার্টারে চেষ্টা করুন।"},{"question":"কনভার্ট করা ফাইল থেকে আবার কনভার্ট করা যায়?","answer":"যায়, তবে করা উচিত নয়। প্রতিবার ক্ষতিকর কনভার্টে মান কমে। সবসময় মূল ফাইল থেকে শুরু করুন। দুটি ফরম্যাট দরকার হলে মূল থেকে দুটি ব্যাচ চালান।"},{"question":"ফোনে ব্যাচ কনভার্ট করা যায়?","answer":"হ্যাঁ। ফোনের ব্রাউজারে গ্যালারি থেকে একাধিক ছবি বেছে নেওয়া যায়। তবে বড় ব্যাচে ফোন ধীর হতে পারে, তাই বিশটির বেশি হলে ডেস্কটপে করা ভালো।"}];
